def encode(text):
    """Run-length encode text that holds no digits. See TASK.md."""
    if any(c.isdigit() for c in text):
        raise ValueError("Text contains digits")

    if not text:
        return ""

    result = []
    i = 0
    while i < len(text):
        char = text[i]
        count = 1
        while i + count < len(text) and text[i + count] == char:
            count += 1

        if count > 1:
            result.append(str(count) + char)
        else:
            result.append(char)

        i += count

    return "".join(result)


def decode(text):
    """Reverse `encode`. See TASK.md."""
    if not text:
        return ""

    result = []
    i = 0

    while i < len(text):
        if text[i].isdigit():
            count_start = i
            while i < len(text) and text[i].isdigit():
                i += 1

            count_str = text[count_start:i]

            # Check for leading zeros
            if len(count_str) > 1 and count_str[0] == '0':
                raise ValueError("Count has leading zero")

            count = int(count_str)

            # Count must be > 1
            if count <= 1:
                raise ValueError("Count must be greater than 1")

            # Must have a character after the count
            if i >= len(text):
                raise ValueError("Count with no character after")

            char = text[i]
            result.append(char * count)
            i += 1
        else:
            result.append(text[i])
            i += 1

    return "".join(result)
